#include <metal_stdlib>
using namespace metal;
kernel void k(texture2d<float> t [[texture(0)]], sampler s [[sampler(0)]],
              device float4* o [[buffer(0)]]) {
  float2 uv = float2(0.500000000f, 0.046875000f);
  float2 grad_dx = float2(0.500000000f, 0.0);
  float2 grad_dy = float2(0.0, 0.031250000f);
  o[0] = t.sample(s, uv, gradient2d(grad_dx, grad_dy));
}
